1188	+/** Private matches play the slice preset (§18 stage 2): two types, eight rubbings, two sources on each of four islands. */
1189	+export const MATCH_PRESET: RulesPresetId = "slice";
1190	+
1191	+/** The centre of a dock's tile, in sub-units: where a moored ship lies, a source stands and a cache is placed. */
1192	+export function dockCentre(map: SeaMapDefinition, dockId: number): { x: number; y: number } {
1193	+  const dock = map.docks[dockId];
1194	+  if (dock === undefined) throw new RangeError(`no dock ${dockId}`);
1195	+  const half = Math.floor(map.subUnitsPerTile / 2);
1196	+  return { x: dock.tileX * map.subUnitsPerTile + half, y: dock.tileY * map.subUnitsPerTile + half };
1197	+}
1198	+
1199	+/** An island's docks, in id order. */
1200	+export function islandDocks(map: SeaMapDefinition, island: number): number[] {
1201	+  return map.docks.filter((dock) => dock.island === island).map((dock) => dock.id);
1202	+}
1203	+
1204	+/**
1205	+ * The ledger's source sites: `sourcesPerIsland` on each regular island, at that island's docks taken in id order (a
1206	+ * dock is reused when the island has fewer docks than sources). Site `j` of island `i` becomes source `source-i-j`.
1207	+ */
1208	+export function sourceSites(map: SeaMapDefinition, presetId: RulesPresetId = MATCH_PRESET): SourceSite[] {
1209	+  const preset = rulesPresets[presetId];
1210	+  const sites: SourceSite[] = [];
1211	+  for (let island = 0; island < preset.islands; island++) {
1212	+    const docks = islandDocks(map, island);
1213	+    if (docks.length === 0) throw new Error(`${map.name}: island ${island} has no dock for its sources`);
1214	+    for (let slot = 0; slot < preset.sourcesPerIsland; slot++) sites.push({ island, ...dockCentre(map, docks[slot % docks.length]!) });
1215	+  }
1216	+  return sites;
1217	+}
