1219	+/**
1220	+ * A fixed assignment for the test-only source layout (`TEST_SOURCES_ENV`): island `i`'s sources get the types of
1221	+ * group `i`, in order, each the next unused copy of that type. The ledger validates the result like any assignment,
1222	+ * so a layout that does not seal every rubbing once is refused.
1223	+ */
1224	+export function layoutAssignment(sites: readonly SourceSite[], layout: readonly (readonly string[])[], presetId: RulesPresetId = MATCH_PRESET): SourceAssignment {
1225	+  const copies = new Map<string, number>();
1226	+  const slots = new Map<number, number>();
1227	+  const sources = sites.map((site) => {
1228	+    const slot = slots.get(site.island) ?? 0;
1229	+    slots.set(site.island, slot + 1);
1230	+    const type = layout[site.island]?.[slot];
1231	+    if (type === undefined || !(RUBBING_TYPES as readonly string[]).includes(type)) {
1232	+      throw new Error(`test source layout: island ${site.island} source ${slot} has no valid type`);
1233	+    }
1234	+    const copy = (copies.get(type) ?? 0) + 1;
1235	+    copies.set(type, copy);
1236	+    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: type as RubbingType, rubbingId: `${type}-${copy}` };
1237	+  });
1238	+  return { preset: presetId, seed: 0, sources };
1239	+}
