1300	+/** What holding E at a dock works on: an island source to collect, or one cached rubbing to claim. */
1301	+export type InteractTarget =
1302	+  | { readonly kind: "collect"; readonly sourceId: string; readonly type: RubbingType }
1303	+  | { readonly kind: "claim"; readonly cacheId: string; readonly rubbingId: string; readonly type: RubbingType };
