1305	+/**
1306	+ * E's target for a player moored at a dock: first the island's unlocked sealed source of a type the player lacks,
1307	+ * then a rubbing of a type they lack in a cache at this dock, each in the fixed type order (ties to the lower source
1308	+ * id, the older cache, the lower rubbing id). None when the player lacks nothing on offer.
1309	+ */
1310	+export function interactTarget(ledger: LedgerState, map: SeaMapDefinition, playerId: string, dockId: number): InteractTarget | undefined {
1311	+  const island = map.docks[dockId]?.island;
1312	+  if (island === undefined || island < 0) return undefined;
1313	+  const held = new Set(heldTypes(ledger, playerId));
1314	+  const source = ledger.sources
1315	+    .filter((each) => each.island === island && each.unlocked && !held.has(each.type) && sealedAt(ledger, each.id, each.rubbingId))
1316	+    .sort((a, b) => typeOrder(a.type) - typeOrder(b.type) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
1317	+  if (source !== undefined) return { kind: "collect", sourceId: source.id, type: source.type };
1318	+  for (const type of ledger.types) {
1319	+    if (held.has(type)) continue;
1320	+    for (const cache of cachesAtDock(ledger, map, dockId)) {
1321	+      const rubbing = cacheRubbings(ledger, cache.id)
1322	+        .filter((each) => each.type === type)
1323	+        .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
1324	+      if (rubbing !== undefined) return { kind: "claim", cacheId: cache.id, rubbingId: rubbing.id, type };
1325	+    }
1326	+  }
1327	+  return undefined;
1328	+}
