1330	+/**
1331	+ * The dock nearest a position by sea (§12: a quitter's cache goes to the nearest reachable dock): the shortest
1332	+ * eight-way path over navigable tiles, ties to the lower dock id. A position whose tile reaches no dock falls back to
1333	+ * the nearest dock in a straight line.
1334	+ */
1335	+export function nearestDockBySea(map: SeaMapDefinition, x: number, y: number): number {
1336	+  const tileX = Math.floor(x / map.subUnitsPerTile);
1337	+  const tileY = Math.floor(y / map.subUnitsPerTile);
1338	+  const costs = seaPathCosts(map, tileX, tileY);
1339	+  let best = -1;
1340	+  let bestCost = Number.POSITIVE_INFINITY;
1341	+  for (const dock of map.docks) {
1342	+    const cost = costs[dock.tileY * map.widthTiles + dock.tileX]!;
1343	+    if (cost < bestCost) {
1344	+      best = dock.id;
1345	+      bestCost = cost;
1346	+    }
1347	+  }
1348	+  if (best >= 0 && bestCost < Number.MAX_SAFE_INTEGER) return best;
1349	+  let nearest = 0;
1350	+  let nearestDistance = Number.POSITIVE_INFINITY;
1351	+  for (const dock of map.docks) {
1352	+    const centre = dockCentre(map, dock.id);
1353	+    const distance = (centre.x - x) ** 2 + (centre.y - y) ** 2;
1354	+    if (distance < nearestDistance) {
1355	+      nearest = dock.id;
1356	+      nearestDistance = distance;
1357	+    }
1358	+  }
1359	+  return nearest;
1360	+}
